// spec: specs/orders.md §34 · кейс .qa/tests/orders/ord-47 · seed: tests/seed.admin.spec.ts (+ test.use на роль)
// #de732f (commit ac29bde): URL по номеру заказа. admin /orders/685 → редирект на /orders/a6f2f8c0-6d4d-4a8b-a03f-44f041778a3d, «הזמנה #685»;
//   /orders/999999, /abc, /0 → «ההזמנה לא נמצאה.» + «חזרה להזמנות», без «נסה שוב», нет ответов ≥400; /edit и /receipt по номеру;
//   buyer /shop/order/685 свой открывается, /shop/order/683 (чужой) — не найден; rep /orders/683 — не найден;
//   dist2 (второй מפיץ, auth/dist2.json) /orders/685 и uuid #685 — не найден; настоящая ошибка (abort rest/v1/orders) → «טעינת ההזמנה נכשלה.» с «נסה שוב».
// Только чтение — @prod-safe. Номера/uuid — из тикета (данные #685 неизменны).
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

const auth = (id: string) => path.resolve(__dirname, '../../../auth', `${id}.json`);
const UUID_685 = 'a6f2f8c0-6d4d-4a8b-a03f-44f041778a3d';
const NOT_FOUND = 'ההזמנה לא נמצאה.';
const LOAD_FAILED = 'טעינת ההזמנה נכשלה.';
const RETRY = 'נסה שוב';

/** Собирает ответы ≥400 от REST/RPC (supabase) — вызвать до goto. */
function watchErrors(page: Page): string[] {
  const bad: string[] = [];
  page.on('response', (r) => {
    if (r.status() >= 400 && /\/(rest|rpc)\/v1\/|\/rest\/v1\//.test(r.url())) bad.push(`${r.status()} ${r.request().method()} ${r.url().replace(/^https?:\/\/[^/]+/, '')}`);
  });
  return bad;
}

async function expectNotFound(page: Page, withListLink = true) {
  await expect(page.getByText(NOT_FOUND, { exact: true })).toBeVisible({ timeout: 30_000 });
  if (withListLink) await expect(page.getByText('חזרה להזמנות', { exact: true })).toBeVisible();
  await expect(page.getByText(RETRY), '«נסה שוב» в состоянии «не найдено» нет').toHaveCount(0);
  await expect(page.getByText(LOAD_FAILED)).toHaveCount(0);
}

test.describe('admin — /orders/<מספר>', () => {
  test.use({ storageState: auth('admin') });

  test('/orders/685 → מפנה להזמנה #685, בלי «נסה שוב» ובלי תשובות ≥400 #de732f @desktop @prod-safe', async ({ page }) => {
    const bad = watchErrors(page);
    await page.goto('/orders/685');
    await expect(page).toHaveURL(new RegExp(`/orders/${UUID_685}$`), { timeout: 30_000 });
    await expect(page.getByRole('heading', { name: 'הזמנה #685' })).toBeVisible({ timeout: 30_000 });
    await expect(page.getByText(RETRY)).toHaveCount(0);
    await expect(page.getByText(LOAD_FAILED)).toHaveCount(0);
    expect(bad, 'нет ответов ≥400').toEqual([]);
  });

  for (const bogus of ['999999', 'abc', '0']) {
    test(`/orders/${bogus} → «ההזמנה לא נמצאה.» + «חזרה להזמנות», בלי «נסה שוב» ובלי ≥400 #de732f @desktop @prod-safe`, async ({ page }) => {
      const bad = watchErrors(page);
      await page.goto(`/orders/${bogus}`);
      await expectNotFound(page);
      expect(bad, 'нет ответов ≥400').toEqual([]);
    });
  }

  test('/orders/685/edit לפי מספר — נפתחת עריכת אותה הזמנה, בלי שגיאה ובלי ≥400 #de732f @desktop @prod-safe', async ({ page }) => {
    const bad = watchErrors(page);
    await page.goto('/orders/685/edit');
    await expect(page).toHaveURL(new RegExp(`/orders/${UUID_685}/edit$`), { timeout: 30_000 });
    await expect(page.getByText(NOT_FOUND)).toHaveCount(0);
    await expect(page.getByText(LOAD_FAILED)).toHaveCount(0);
    await expect(page.getByText(RETRY)).toHaveCount(0);
    expect(bad, 'нет ответов ≥400').toEqual([]);
  });

  test('/orders/685/receipt לפי מספר — נפתח הקבלה של אותה הזמנה, בלי שגיאה ובלי ≥400 #de732f @desktop @prod-safe', async ({ page }) => {
    const bad = watchErrors(page);
    await page.goto('/orders/685/receipt');
    await expect(page).toHaveURL(new RegExp(`/orders/${UUID_685}/receipt$`), { timeout: 30_000 });
    await expect(page.getByRole('main')).not.toBeEmpty();
    await expect(page.getByText(NOT_FOUND)).toHaveCount(0);
    await expect(page.getByText(LOAD_FAILED)).toHaveCount(0);
    await expect(page.getByText(RETRY)).toHaveCount(0);
    expect(bad, 'нет ответов ≥400').toEqual([]);
  });

  test('/orders/<uuid> — הנתיב הקודם עובד כמו קודם #de732f @desktop @prod-safe', async ({ page }) => {
    const bad = watchErrors(page);
    await page.goto(`/orders/${UUID_685}`);
    await expect(page.getByRole('heading', { name: 'הזמנה #685' })).toBeVisible({ timeout: 30_000 });
    await expect(page).toHaveURL(new RegExp(`/orders/${UUID_685}$`));
    expect(bad, 'нет ответов ≥400').toEqual([]);
  });

  test('שגיאת טעינה אמיתית (abort של orders) — «טעינת ההזמנה נכשלה.» עם «נסה שוב» #de732f @desktop @prod-safe', async ({ page }) => {
    test.setTimeout(90_000);
    await page.route(/\/rest\/v1\/orders\?/, (route) => route.abort('failed'));
    await page.goto(`/orders/${UUID_685}`);
    await expect(page.getByText(LOAD_FAILED, { exact: true })).toBeVisible({ timeout: 45_000 });
    await expect(page.getByRole('button', { name: RETRY })).toBeVisible();
    await expect(page.getByText(NOT_FOUND), 'настоящая ошибка — не «не найдено»').toHaveCount(0);
  });
});

test.describe('buyer — /shop/order/<מספר>', () => {
  test.use({ storageState: auth('buyer') });

  test('/shop/order/685 (שלו) נפתחת; /shop/order/683 (של אחר) — «לא נמצאה» #de732f @desktop @prod-safe', async ({ page }) => {
    const bad = watchErrors(page);
    await page.goto('/shop/order/685');
    await expect(page.getByText(/685/).first()).toBeVisible({ timeout: 30_000 });
    await expect(page.getByText(NOT_FOUND)).toHaveCount(0);
    await expect(page.getByText(LOAD_FAILED)).toHaveCount(0);
    await expect(page.getByText(RETRY)).toHaveCount(0);

    await page.goto('/shop/order/683');
    await expectNotFound(page, false);
    expect(bad, 'нет ответов ≥400').toEqual([]);
  });
});

test.describe('rep — /orders/<מספר> של לקוח אחר', () => {
  test.use({ storageState: auth('rep') });

  test('rep /orders/683 — «ההזמנה לא נמצאה.», בלי «נסה שוב» #de732f @desktop @prod-safe', async ({ page }) => {
    await page.goto('/orders/683');
    await expectNotFound(page, false);
    await expect(page.getByRole('heading', { name: 'הזמנה #683' })).toHaveCount(0);
  });
});

test.describe('dist2 — מפיץ שני, בידוד עסקים', () => {
  test.use({ storageState: auth('dist2') });

  test('dist2 /orders/685 ו-/orders/<uuid של #685> — «לא נמצאה», ההזמנה של עסק אחר לא נחשפת #de732f @desktop @prod-safe', async ({ page }) => {
    await page.goto('/orders/685');
    await expectNotFound(page, false);
    await expect(page.getByRole('heading', { name: 'הזמנה #685' })).toHaveCount(0);

    await page.goto(`/orders/${UUID_685}`);
    await expectNotFound(page, false);
    await expect(page.getByRole('heading', { name: 'הזמנה #685' })).toHaveCount(0);
  });
});
